<script setup>
import {computed,onMounted,onBeforeUnmount,ref} from 'vue'
import {onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router'
import {api} from '../api'
import {experience} from '../composables/experience'
import {auth} from '../composables/auth'
import PracticeRecords from './PracticeRecords.vue'
const props=defineProps({course:Object})
const practice=computed(()=>props.course.canPractice && experience.student)
const base=`/courses/${props.course.id}/gradebook`
const data=ref(null),error=ref(''),notice=ref(''),busy=ref(false),selected=ref(''),drafts=ref({}),draftVersions=ref({}),form=ref(null)
const categories={offline_assignment:'線下作業',assignment:'PDF 報告作業',quiz:'小考',midterm:'期中考試',final:'期末考試',other:'其他'}
const item=computed(()=>data.value?.items.find(x=>x.id===selected.value))
const linked=computed(()=>!!(item.value?.sourceAssignmentId || item.value?.sourceReportId))
const dirty=computed(()=>Object.keys(drafts.value).length>0 || !!form.value)
const writable=computed(()=>data.value?.staff && props.course.status!=='archived')
const percent=value=>value==null?'尚無得分':`${Number(value).toFixed(2)} 分`
function entry(studentId){return data.value?.scores.find(x=>x.itemId===selected.value && x.studentId===studentId)}
function value(studentId){return studentId in drafts.value?drafts.value[studentId]:entry(studentId)?.score??''}
function editScore(studentId,text){const old=entry(studentId)?.score;const next=text===''?'':Number(text);if(next===(old??'')){delete drafts.value[studentId];delete draftVersions.value[studentId]}else{if(!(studentId in drafts.value))draftVersions.value[studentId]=entry(studentId)?.version??0;drafts.value[studentId]=next}}
async function load(){data.value=await api(base);if(!data.value.items.some(x=>x.id===selected.value))selected.value=data.value.items[0]?.id || ''}
async function run(action){busy.value=true;error.value='';notice.value='';try{await action()}catch(e){error.value=e.message}finally{busy.value=false}}
function choose(event){if(Object.keys(drafts.value).length && !confirm('此項目有尚未儲存的得分，確定放棄並切換？')){event.target.value=selected.value;return}drafts.value={};draftVersions.value={};selected.value=event.target.value}
function edit(item=null){if(form.value && !confirm('確定放棄目前項目編輯？'))return;form.value=item?{...item,expectedVersion:item.version}:{title:'',category:'offline_assignment',maxScore:100,weight:1}}
async function saveItem(){await run(async()=>{await api(`${base}/items${form.value.id?'/'+form.value.id:''}`,{method:form.value.id?'PUT':'POST',body:form.value});form.value=null;await load();notice.value='評分項目與權重已儲存，平均分數已重新計算。'})}
async function saveScore(student){await run(async()=>{const score=drafts.value[student.id];await api(`${base}/items/${selected.value}/score`,{method:'PUT',body:{studentId:student.id,score:score===''?null:score,expectedVersion:draftVersions.value[student.id]??0}});delete drafts.value[student.id];delete draftVersions.value[student.id];await load();notice.value='得分已儲存，平均分數已更新。'})}
function guard(){return !dirty.value || confirm('評分管理有尚未儲存的修改，確定離開？')}
onBeforeRouteLeave(guard)
onBeforeRouteUpdate((to,from)=>to.fullPath===from.fullPath || guard())
function unload(event){if(dirty.value){event.preventDefault();event.returnValue=''}}
window.addEventListener('beforeunload',unload)
onBeforeUnmount(()=>window.removeEventListener('beforeunload',unload))
onMounted(()=>{if(!practice.value)run(load)})
</script>
<template><PracticeRecords v-if="course.canPractice" :course="course" /><section v-if="!practice" class="surface form-surface gradebook-panel"><div class="section-title"><div><h2>測驗／作業成績管理</h2><p class="muted">線上／課後測驗、PDF 作業與線下評量統一管理權重與平均。連動成績請從原評量評閱給分。</p></div><button v-if="writable" class="button primary" :disabled="busy" @click="edit()">新增評分項目</button></div><p v-if="error" class="error-box" role="alert">{{error}}</p><p v-if="notice" class="success-box" role="status">{{notice}}</p><template v-if="data"><div class="gradebook-summary"><div><span>全班加權平均（百分制）</span><strong>{{percent(data.classAverage)}}</strong><small>{{data.gradedStudentCount}} 位同學已有得分</small></div><div v-if="!data.staff"><span>我的加權平均（百分制）</span><strong>{{percent(data.averages[0]?.average)}}</strong><small>{{data.averages[0]?.recordedCount??0}} 項已登錄</small></div><div><span>評分項目</span><strong>{{data.items.length}} 項</strong><small>各項滿分與權重可分別設定</small></div></div><p class="field-hint">個人平均＝各項「得分 ÷ 滿分 × 100」依權重加權；未登錄不計入，0 分計入。全班平均取有成績同學的個人加權平均。此處登錄後本人即可查看。</p><p v-if="data.isPractice" class="submission-notice">學生體驗可查看全班統計，沒有正式學生得分。</p><form v-if="form && writable" class="question-editor" @submit.prevent="saveItem"><h3>{{form.id?'編輯評分項目':'新增評分項目'}}</h3><fieldset :disabled="busy"><div class="form-grid"><label>項目名稱<input :readonly="!!(form.sourceAssignmentId || form.sourceReportId)" v-model="form.title" required maxlength="200" /></label><label>評量類型<select :disabled="!!(form.sourceAssignmentId || form.sourceReportId)" v-model="form.category"><option v-for="(label,key) in categories" :key="key" :value="key">{{label}}</option></select></label><label>滿分<input :readonly="!!(form.sourceAssignmentId || form.sourceReportId)" v-model.number="form.maxScore" type="number" min="0.01" max="999999" step="0.01" required /></label><label>成績權重<input v-model.number="form.weight" type="number" min="0.001" max="999999" step="0.001" required /></label></div><p class="field-hint">線上測驗與 PDF 作業在此僅調整權重，分數由原評量連動，不重複手動登分。權重為相對比例，例如 30 與 70；不要求總和為 100。修改滿分或權重會重新計算平均。</p><button class="button primary">儲存項目</button><button type="button" class="button secondary" @click="form=null">取消</button></fieldset></form><template v-if="data.items.length"><h3>評分項目</h3><div class="table-scroll"><table class="data-table"><thead><tr><th>項目</th><th>類型</th><th>滿分</th><th>權重</th><th>全班平均（百分制）</th><th v-if="writable">操作</th></tr></thead><tbody><tr v-for="row in data.items" :key="row.id"><td>{{row.title}}</td><td>{{categories[row.category]}}</td><td>{{row.maxScore}}</td><td>{{row.weight}}</td><td>{{percent(data.itemAverages.find(a=>a.itemId===row.id)?.average)}}</td><td v-if="writable"><button class="text-button" :disabled="busy" @click="edit(row)">編輯項目</button></td></tr></tbody></table></div><template v-if="data.staff"><label>登錄項目<select aria-label="登錄項目" :value="selected" :disabled="busy" @change="choose"><option v-for="row in data.items" :key="row.id" :value="row.id">{{row.title}}（滿分 {{row.maxScore}}）</option></select></label><div v-if="linked" class="submission-notice">此項目由原評量連動。<RouterLink :to="item.sourceAssignmentId?`/quizzes/${item.sourceAssignmentId}`:`/reports/${item.sourceReportId}`">前往評閱與給分 →</RouterLink></div><p v-else class="field-hint">空白表示未登錄；若需計為零分，請輸入 0。每位同學分別儲存，其他未儲存輸入會保留。</p><div class="table-scroll"><table class="data-table"><thead><tr><th>學號</th><th>姓名</th><th>得分</th><th>個人加權平均（百分制）</th><th v-if="writable && !linked">操作</th></tr></thead><tbody><tr v-for="student in data.students" :key="student.id"><td>{{student.studentNumber || '未填學號'}}</td><td>{{student.displayName}}</td><td><input v-if="writable && !linked" type="number" min="0" :max="item?.maxScore" step="0.01" :aria-label="`${student.displayName} 得分`" :value="value(student.id)" :disabled="busy" @input="editScore(student.id,$event.target.value)" /><span v-else>{{entry(student.id)?.score??'未登錄'}}</span></td><td>{{percent(data.averages.find(x=>x.studentId===student.id)?.average)}}</td><td v-if="writable && !linked"><button class="button secondary" :disabled="busy || !(student.id in drafts)" @click="saveScore(student)">儲存得分</button></td></tr></tbody></table></div></template><template v-else><h3>我的得分</h3><div class="table-scroll"><table class="data-table"><thead><tr><th>項目</th><th>得分／滿分</th><th>權重</th></tr></thead><tbody><tr v-for="row in data.items" :key="row.id"><td>{{row.title}}</td><td>{{data.scores.find(s=>s.itemId===row.id)?.score??'未登錄'}} / {{row.maxScore}}</td><td>{{row.weight}}</td></tr></tbody></table></div></template></template><p v-else class="empty-inline">尚無評分項目；教師／助教可新增項目並登錄得分。</p></template></section></template>
